CREATE TABLE operations(id TEXT NOT NULL PRIMARY KEY,kind TEXT NOT NULL,resource_id TEXT NOT NULL,digest TEXT NOT NULL,state TEXT NOT NULL,phase TEXT NOT NULL,request TEXT NOT NULL,result TEXT NOT NULL DEFAULT '{}',error_code TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE sites(id TEXT NOT NULL PRIMARY KEY,metadata TEXT NOT NULL);
CREATE TABLE domains(id TEXT NOT NULL PRIMARY KEY,site_id TEXT NOT NULL,metadata TEXT NOT NULL);
CREATE TABLE backups(id TEXT NOT NULL PRIMARY KEY,site_id TEXT NOT NULL,metadata TEXT NOT NULL);
CREATE TABLE recovery(id TEXT NOT NULL PRIMARY KEY,site_id TEXT NOT NULL,metadata TEXT NOT NULL);
